import{_ as s,o as t,c as i,a2 as o}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"JsonLoggerOutputSink — JSON 日志输出","description":"将事件写入 events.jsonl，将推理记录写入 inferences.json","frontmatter":{"title":"JsonLoggerOutputSink — JSON 日志输出","description":"将事件写入 events.jsonl，将推理记录写入 inferences.json"},"headers":[],"relativePath":"architecture/infrastructure/output/json_logger.md","filePath":"architecture/infrastructure/output/json_logger.md","lastUpdated":1773326634000}'),n={name:"architecture/infrastructure/output/json_logger.md"};function a(c,e,r,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="jsonloggeroutputsink-—-json-日志输出" tabindex="-1">JsonLoggerOutputSink — JSON 日志输出 <a class="header-anchor" href="#jsonloggeroutputsink-—-json-日志输出" aria-label="Permalink to &quot;JsonLoggerOutputSink — JSON 日志输出&quot;">​</a></h1><p><strong>源文件</strong>：<code>src/streammuse/infrastructure/output/json_logger.py</code></p><p>将音符事件和推理信息持久化为 JSON 格式，用于事后分析和性能评估。</p><hr><h2 id="jsonloggeroutputsink" tabindex="-1"><code>JsonLoggerOutputSink</code> <a class="header-anchor" href="#jsonloggeroutputsink" aria-label="Permalink to &quot;`JsonLoggerOutputSink`&quot;">​</a></h2><h3 id="init-session-dir-path-none" tabindex="-1"><code>__init__(session_dir: Path) -&gt; None</code> <a class="header-anchor" href="#init-session-dir-path-none" aria-label="Permalink to &quot;`__init__(session_dir: Path) -&gt; None`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>session_dir</code></td><td>会话目录（通常为 <code>logs/session_YYYYMMDD-HHMMSS/</code>）</td></tr></tbody></table><p>初始化时创建以下对象：</p><ul><li><code>events_file = session_dir / &quot;events.jsonl&quot;</code> ← 逐行追加</li><li><code>inferences_file = session_dir / &quot;inferences.json&quot;</code> ← 最终写入</li><li><code>MetricsCalculator</code> 实例（实时累积统计）</li><li><code>inferences: list[InferenceEvent]</code>（内存中累积）</li></ul><hr><h3 id="output-event-event-source" tabindex="-1"><code>output_event(event, source)</code> <a class="header-anchor" href="#output-event-event-source" aria-label="Permalink to &quot;`output_event(event, source)`&quot;">​</a></h3><p>将 <code>MusicalEvent</code> 转换为 <code>LogEvent</code> 并：</p><ol><li>追加到 <code>MetricsCalculator</code>（<code>add_event()</code>）</li><li>以 JSON Lines 格式写入 <code>events.jsonl</code></li></ol><p>写入格式（每行一个 JSON 对象）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1700000000.123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tick&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;event_type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;note_on&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pitch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;velocity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><hr><h3 id="log-inference-request-response-latency-ms-server-process-ms" tabindex="-1"><code>log_inference(request, response, latency_ms, server_process_ms)</code> <a class="header-anchor" href="#log-inference-request-response-latency-ms-server-process-ms" aria-label="Permalink to &quot;`log_inference(request, response, latency_ms, server_process_ms)`&quot;">​</a></h3><blockquote><p>此方法不在 <code>OutputSink</code> Protocol 中，由服务层通过 <code>hasattr</code> 检测调用。</p></blockquote><p>创建 <code>InferenceEvent</code> 并：</p><ol><li>追加到 <code>self.inferences</code> 列表（内存）</li><li>追加到 <code>MetricsCalculator</code>（<code>add_inference()</code>）</li></ol><p><strong>不立即写文件</strong>，在 <code>close()</code> 或 <code>save_inferences()</code> 时集中写入，保证 <code>inferences.json</code> 是完整的 JSON 数组。</p><hr><h3 id="save-metrics-session-config-dict-none" tabindex="-1"><code>save_metrics(session_config: Dict) -&gt; None</code> <a class="header-anchor" href="#save-metrics-session-config-dict-none" aria-label="Permalink to &quot;`save_metrics(session_config: Dict) -&gt; None`&quot;">​</a></h3><p>调用 <code>MetricsCalculator</code> 生成并写入：</p><ul><li><code>performance.json</code>：延迟百分位、事件计数、音乐分析</li><li><code>statistics.csv</code>：摘要指标</li></ul><hr><h3 id="save-inferences-none" tabindex="-1"><code>save_inferences() -&gt; None</code> <a class="header-anchor" href="#save-inferences-none" aria-label="Permalink to &quot;`save_inferences() -&gt; None`&quot;">​</a></h3><p>将 <code>self.inferences</code> 序列化为 JSON 数组写入 <code>inferences.json</code>。</p><hr><h3 id="output-tick-output-stats-output-status-output-config" tabindex="-1"><code>output_tick</code>, <code>output_stats</code>, <code>output_status</code>, <code>output_config</code> <a class="header-anchor" href="#output-tick-output-stats-output-status-output-config" aria-label="Permalink to &quot;`output_tick`, `output_stats`, `output_status`, `output_config`&quot;">​</a></h3><p>均为空操作（no-op）。</p><h3 id="close" tabindex="-1"><code>close()</code> <a class="header-anchor" href="#close" aria-label="Permalink to &quot;`close()`&quot;">​</a></h3><p>调用 <code>save_inferences()</code>（如 <code>close()</code> 中包含此逻辑时）。注意：CLI 中通过 <code>cleanup()</code> 函数显式调用 <code>save_metrics()</code> 和 <code>save_inferences()</code>。</p><hr><h2 id="文件输出示例" tabindex="-1">文件输出示例 <a class="header-anchor" href="#文件输出示例" aria-label="Permalink to &quot;文件输出示例&quot;">​</a></h2><p>运行结束后，会话目录中包含：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>session_20241201-120000/</span></span>\n<span class="line"><span>├── events.jsonl       # 每行一个事件，实时追加</span></span>\n<span class="line"><span>├── inferences.json    # 所有推理记录，退出时写入</span></span>\n<span class="line"><span>├── performance.json   # MetricsCalculator 生成</span></span>\n<span class="line"><span>└── statistics.csv     # 摘要 CSV</span></span></code></pre></div>',37)])])}const k=s(n,[["render",a]]);export{u as __pageData,k as default};
